-- 1. S1
BEGIN;
-- 2. S1
UPDATE pizzeria SET rating = 5 WHERE name = 'Pizza Hut';
-- 3. S1: видит 5 — свои изменения видны внутри транзакции
SELECT * FROM pizzeria WHERE name = 'Pizza Hut';
-- 4. S2: видит старое значение — изменения S1 не зафиксированы
SELECT * FROM pizzeria WHERE name = 'Pizza Hut';
-- 5. S1
COMMIT;
-- 6. S2: теперь видит 5
SELECT * FROM pizzeria WHERE name = 'Pizza Hut';

-- 1. S1
BEGIN TRANSACTION ISOLATION LEVEL READ COMMITTED;
-- 2. S2
BEGIN TRANSACTION ISOLATION LEVEL READ COMMITTED;
-- 3. S1: 4.6
SELECT * FROM pizzeria WHERE name = 'Pizza Hut';
-- 4. S2: 4.6
SELECT * FROM pizzeria WHERE name = 'Pizza Hut';
-- 5. S1
UPDATE pizzeria SET rating = 4 WHERE name = 'Pizza Hut';
-- 6. S2: зависает — строка заблокирована S1
UPDATE pizzeria SET rating = 3.6 WHERE name = 'Pizza Hut';
-- 7. S1: после COMMIT UPDATE в S2 выполняется
COMMIT;
-- 8. S2
COMMIT;
-- 9. S1 и S2: оба видят 3.6
SELECT * FROM pizzeria WHERE name = 'Pizza Hut';

-- 1. S1
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;
-- 2. S2
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;
-- 3. S1: 4.6
SELECT * FROM pizzeria WHERE name = 'Pizza Hut';
-- 4. S2: 4.6
SELECT * FROM pizzeria WHERE name = 'Pizza Hut';
-- 5. S1
UPDATE pizzeria SET rating = 4 WHERE name = 'Pizza Hut';
-- 6. S2: зависает
UPDATE pizzeria SET rating = 3.6 WHERE name = 'Pizza Hut';
-- 7. S1: в S2 сразу ERROR: could not serialize access due to concurrent update
COMMIT;
-- 8. S2: транзакция уже сломана — COMMIT выполнит ROLLBACK
COMMIT;
-- 9. S1 и S2: оба видят 4
SELECT * FROM pizzeria WHERE name = 'Pizza Hut';

-- 1. S1
BEGIN TRANSACTION ISOLATION LEVEL READ COMMITTED;
-- 2. S2
BEGIN TRANSACTION ISOLATION LEVEL READ COMMITTED;
-- 3. S1: старое значение
SELECT * FROM pizzeria WHERE name = 'Pizza Hut';
-- 4. S2
UPDATE pizzeria SET rating = 3.6 WHERE name = 'Pizza Hut';
-- 5. S2
COMMIT;
-- 6. S1: уже 3.6 — внутри той же транзакции!
SELECT * FROM pizzeria WHERE name = 'Pizza Hut';
-- 7. S1
COMMIT;

-- 1. S1
BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;
-- 2. S2
BEGIN TRANSACTION ISOLATION LEVEL READ COMMITTED;
-- 3. S1: старое значение
SELECT * FROM pizzeria WHERE name = 'Pizza Hut';
-- 4. S2
UPDATE pizzeria SET rating = 3.0 WHERE name = 'Pizza Hut';
-- 5. S2
COMMIT;
-- 6. S1: то же старое значение
SELECT * FROM pizzeria WHERE name = 'Pizza Hut';
-- 7. S1
COMMIT;
-- 8. S1: теперь 3.0
SELECT * FROM pizzeria WHERE name = 'Pizza Hut';

-- 1. S1
BEGIN TRANSACTION ISOLATION LEVEL READ COMMITTED;
-- 2. S2
BEGIN TRANSACTION ISOLATION LEVEL READ COMMITTED;
-- 3. S1: исходная сумма
SELECT SUM(rating) FROM pizzeria;
-- 4. S2
INSERT INTO pizzeria (id, name, rating) VALUES (10, 'Kazan Pizza', 5);
-- 5. S2
COMMIT;
-- 6. S1: сумма выросла на 5 — появилась строка-«фантом»
SELECT SUM(rating) FROM pizzeria;
-- 7. S1
COMMIT;

-- 1. S1
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;
-- 2. S2
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;
-- 3. S1: исходная сумма (у тебя — 26.9)
SELECT SUM(rating) FROM pizzeria;
-- 4. S2
INSERT INTO pizzeria (id, name, rating) VALUES (11, 'Kazan Pizza 2', 4);
-- 5. S2
COMMIT;
-- 6. S1: та же сумма — фантома нет
SELECT SUM(rating) FROM pizzeria;
-- 7. S1
COMMIT;
-- 8. S1: сумма выросла на 4 (у тебя — 30.9)
SELECT SUM(rating) FROM pizzeria;

-- 1. S1
BEGIN;
-- 2. S2
BEGIN;
-- 3. S1: блокирует строку id = 1
UPDATE pizzeria SET rating = 4 WHERE id = 1;
-- 4. S2: блокирует строку id = 2
UPDATE pizzeria SET rating = 4 WHERE id = 2;
-- 5. S1: ждёт id = 2
UPDATE pizzeria SET rating = 5 WHERE id = 2;
-- 6. S2: ждёт id = 1 → цикл → ERROR: deadlock detected
UPDATE pizzeria SET rating = 5 WHERE id = 1;
-- 7. S1: ожидание снято — UPDATE выполнен, коммитим
COMMIT;
-- 8. S2: транзакция откачена, COMMIT выполнит ROLLBACK
COMMIT;
